import { describe, expect, test } from "bun:test";
import { summariseTrace, type SpanNode } from "../src/obs/summary.ts";

const span = (name: string, kind: string, o: Partial<SpanNode> = {}): SpanNode => ({
  name, kind, status: "ok", attributes: {}, durationMs: 1, children: [], ...o,
});

describe("summariseTrace", () => {
  test("empty-ish trace", () => {
    const s = summariseTrace(span("review", "WORKFLOW"));
    expect(s).toEqual({ toolCalls: 0, errors: [], retries: 0, costUsd: null, slowest: null, oneLine: "0 tool calls" });
  });

  test("full trace", () => {
    const root = span("review", "WORKFLOW", { children: [span("coordinator", "AGENT", { children: [
      span("ingest", "TOOL", { durationMs: 10, attributes: { "roster.cost_usd": 0.1 } }),
      span("install", "TOOL", { status: "error", durationMs: 90, attributes: { "error.message": "boom", "roster.attempt": 2 } }),
      span("test", "TOOL", { status: "error", durationMs: 40, attributes: { "roster.cost_usd": 0.11, "roster.attempt": 1 } }),
