// Focused failure context for the coordinator: a span tree boiled down to counts, errors and cost (DESIGN.md §"Observability (neatlogs)").
export type SpanNode = {
  name: string;
  kind: string;
  status: "ok" | "error";
  attributes: Record<string, unknown>;
  durationMs: number;
  children: SpanNode[];
};

export type TraceSummary = {
  toolCalls: number;
  errors: { name: string; message?: string }[];
  retries: number;
  costUsd: number | null;
  slowest: { name: string; durationMs: number } | null;
  oneLine: string;
};

const count = (n: number, one: string, many: string): string => `${n} ${n === 1 ? one : many}`;

export function summariseTrace(root: SpanNode): TraceSummary {
  let toolCalls = 0;
  let retries = 0;
  let costSum = 0;
  let hasCost = false;
  let slowest: TraceSummary["slowest"] = null;
  const errors: TraceSummary["errors"] = [];

  const visit = (span: SpanNode): void => {
    if (span.kind === "TOOL") {
      toolCalls++;
      if (!slowest || span.durationMs > slowest.durationMs) slowest = { name: span.name, durationMs: span.durationMs };
    }
    if (span.status === "error") {
      const message = span.attributes["error.message"];
      errors.push(typeof message === "string" ? { name: span.name, message } : { name: span.name });
    }
    const attempt = span.attributes["roster.attempt"];
    if (typeof attempt === "number" && attempt > 1) retries++;
    const cost = span.attributes["roster.cost_usd"];
    if (typeof cost === "number" && Number.isFinite(cost)) {
      costSum += cost;
      hasCost = true;
    }
    for (const child of span.children) visit(child);
  };
  visit(root);

  const costUsd = hasCost ? costSum : null;
  const parts = [count(toolCalls, "tool call", "tool calls")];
  if (errors.length > 0) parts.push(`${count(errors.length, "error", "errors")} (${errors.map((e) => e.name).join(", ")})`);
  if (retries > 0) parts.push(count(retries, "retry", "retries"));
  if (costUsd !== null) parts.push(`$${costUsd.toFixed(2)}`);

  return { toolCalls, errors, retries, costUsd, slowest, oneLine: parts.join(", ") };
}

import { describe, expect, test } from "bun:test";
import { summariseTrace, type SpanNode } from "../src/obs/summary.ts";

const span = (name: string, kind: string, o: Partial<SpanNode> = {}): SpanNode => ({
  name,
  kind,
  status: "ok",
  attributes: {},
  durationMs: 1,
  children: [],
  ...o,
});

describe("summariseTrace", () => {
  test("trace with no tool spans", () => {
    const s = summariseTrace(span("review", "WORKFLOW"));
    expect(s).toEqual({ toolCalls: 0, errors: [], retries: 0, costUsd: null, slowest: null, oneLine: "0 tool calls" });
  });

  test("full trace", () => {
    const root = span("review", "WORKFLOW", {
      children: [
        span("coordinator", "AGENT", {
          children: [
            span("ingest", "TOOL", { durationMs: 10, attributes: { "roster.cost_usd": 0.1 } }),
            span("install", "TOOL", {
              status: "error",
              durationMs: 90,
              attributes: { "error.message": "boom", "roster.attempt": 2 },
            }),
            span("test", "TOOL", {
              status: "error",
              durationMs: 40,
              attributes: { "roster.cost_usd": 0.11, "roster.attempt": 1 },
            }),
          ],
        }),
      ],
    });
    const s = summariseTrace(root);
    expect(s.toolCalls).toBe(3);
    expect(s.errors).toEqual([{ name: "install", message: "boom" }, { name: "test" }]);
    expect(s.retries).toBe(1);
    expect(s.costUsd).toBeCloseTo(0.21);
    expect(s.slowest).toEqual({ name: "install", durationMs: 90 });
    expect(s.oneLine).toBe("3 tool calls, 2 errors (install, test), 1 retry, $0.21");
  });

  test("plurals, and non-numeric attributes are ignored", () => {
    const root = span("r", "WORKFLOW", {
      children: [
        span("a", "TOOL", { attributes: { "roster.attempt": 3, "roster.cost_usd": "x" } }),
        span("b", "TOOL", { attributes: { "roster.attempt": 2 } }),
      ],
    });
    const s = summariseTrace(root);
    expect(s.costUsd).toBeNull();
    expect(s.oneLine).toBe("2 tool calls, 2 retries");
    expect(summariseTrace(span("t", "TOOL")).oneLine).toBe("1 tool call");
  });
});
